int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    // Implement the decoding logic with stack-based processing of nested structures
    std::stack<int> depth_stack;
    std::vector<lazy_entry> buffer;
    const char* cursor = start;

    while (cursor < end && item_limit > 0) {
        if (*cursor == 'i') {
            // Handle integers
            cursor++;
            const char* num_start = cursor;
            while (cursor < end && *cursor != 'e') {
                if (!isdigit(*cursor)) {
                    ec = error_code::invalid_integer;
                    if (error_pos)
                        *error_pos = cursor - start;
                    return 1;
                }
                cursor++;
            }
            if (cursor >= end) {
                ec = error_code::unexpected_eof;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            int value = std::stoi(std::string(num_start, cursor));
            buffer.push_back(lazy_entry(value));
            item_limit--;
        } else if (*cursor == 'l') {
            // Handle lists
            if (depth_stack.size() >= depth_limit) {
                ec = error_code::depth_limit_exceeded;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            depth_stack.push(depth_stack.size() + 1);
            buffer.push_back(lazy_entry());
        } else if (*cursor == 'd') {
            // Handle dictionaries
            if (depth_stack.size() >= depth_limit) {
                ec = error_code::depth_limit_exceeded;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            depth_stack.push(depth_stack.size() + 1);
            buffer.push_back(lazy_entry());
        } else if (*cursor == 'e') {
            // End of current structure
            if (buffer.empty()) {
                ec = error_code::invalid_structure;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            if (depth_stack.empty()) {
                ec = error_code::invalid_structure;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            lazy_entry parent;
            while (!buffer.empty() && !buffer.back().is_structure()) {
                parent.add_child(buffer.back());
                buffer.pop_back();
            }
            if (buffer.empty()) {
                ec = error_code::invalid_structure;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            buffer.pop_back();
            buffer.push_back(parent);
            depth_stack.pop();
        } else {
            // Handle string keys or values
            const char* str_start = cursor;
            while (cursor < end && *cursor != ':' && *cursor != 'e') {
                cursor++;
            }
            if (cursor >= end || *cursor == 'e') {
                ec = error_code::unexpected_eof;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            int len = std::stoi(std::string(str_start, cursor));
            cursor++;
            if (cursor + len > end) {
                ec = error_code::unexpected_eof;
                if (error_pos)
                    *error_pos = cursor - start;
                return 1;
            }
            std::string str(cursor, cursor + len);
            buffer.push_back(lazy_entry(str));
            item_limit--;
            cursor += len;
        }
        cursor++;
    }

    if (cursor != end) {
        ec = error_code::unexpected_data;
        if (error_pos)
            *error_pos = cursor - start;
        return 1;
    }

    if (buffer.size() != 1) {
        ec = error_code::invalid_structure;
        if (error_pos)
            *error_pos = end - start;
        return 1;
    }

    ret = buffer[0];
    return 0;
}

