int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::vector<std::pair<char const*, lazy_entry*>> stack;
    char const* pos = start;
    lazy_entry* current = &ret;
    int depth = 0;
    int items_decoded = 0;

    while (pos < end && items_decoded < item_limit) {
        if (depth >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos)
                *error_pos = pos - start;
            return 1;
        }

        if (*pos == 'd') {
            current->as_dict = new std::map<std::string, lazy_entry*>();
            stack.emplace_back(pos, current);
            current = &lazy_entry();
            depth++;
            pos++;
            continue;
        }

        if (*pos == 'l') {
            current->as_list = new std::vector<lazy_entry*>();
            stack.emplace_back(pos, current);
            current = &lazy_entry();
            depth++;
            pos++;
            continue;
        }

        if (*pos == 'i') {
            pos++;
            char const* num_start = pos;
            while (pos < end && *pos != 'e') {
                if (!std::isdigit(*pos)) {
                    ec = error_code::invalid_integer_format;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }
                pos++;
            }
            if (pos >= end) {
                ec = error_code::unexpected_end_of_input;
                if (error_pos)
                    *error_pos = pos - start;
                return 1;
            }

            std::string num_str(num_start, pos - num_start);
            try {
                current->as_integer = std::stoll(num_str);
            } catch (...) {
                ec = error_code::integer_out_of_range;
                if (error_pos)
                    *error_pos = pos - start;
                return 1;
            }

            items_decoded++;
            pos++;
            continue;
        }

        if (*pos == 'e') {
            if (stack.empty()) {
                ec = error_code::unexpected_end_of_structure;
                if (error_pos)
                    *error_pos = pos - start;
                return 1;
            }

            auto [prev_pos, parent] = stack.back();
            stack.pop_back();
            if (*prev_pos == 'd') {
                std::string key = current->as_string;
                parent->as_dict->emplace(key, current);
            } else if (*prev_pos == 'l') {
                parent->as_list->push_back(current);
            }

            current = parent;
            depth--;
            pos++;
            continue;
        }

        // Handle strings
        {
            char const* len_start = pos;
            while (pos < end && *pos != ':') {
                if (!std::isdigit(*pos)) {
                    ec = error_code::invalid_string_length;
                    if (error_pos)
                        *error_pos = pos - start;
                    return 1;
                }
                pos++;
            }

            if (pos >= end) {
                ec = error_code::unexpected_end_of_input;
                if (error_pos)
                    *error_pos = pos - start;
                return 1;
            }

            std::string len_str(len_start, pos - len_start);
            int len = std::stoi(len_str);
            if (pos + len > end) {
                ec = error_code::string_length_exceeds_input;
                if (error_pos)
                    *error_pos = pos - start;
                return 1;
            }

            current->as_string = std::string(pos + 1, len);
            items_decoded++;
            pos += len + 1;
            continue;
        }
    }

    if (pos != end) {
        ec = error_code::trailing_data;
        if (error_pos)
            *error_pos = pos - start;
        return 1;
    }

    if (depth != 0) {
        ec = error_code::unbalanced_structure;
        return 1;
    }

    ec = error_code::success;
    return 0;
}

int decode_from_chars(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    const char* pos = start;
    int depth = 0;

    while (pos < end && item_limit-- > 0) {
        if (depth >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos)
                *error_pos = static_cast<int>(pos - start);
            return static_cast<int>(ec);
        }

        switch (*pos) {
            case 'd':
                depth_stack.push(depth);
                depth++;
                break;
            case 'l':
                depth_stack.push(depth);
                depth++;
                break;
            case 'i':
                // Parse integer
                pos++;
                const char* end_int = pos;
                while (end_int < end && isdigit(*end_int))
                    end_int++;

                if (end_int == end || *end_int != 'e') {
                    ec = error_code::invalid_integer;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return static_cast<int>(ec);
                }

                try {
                    long long value = std::stoll(std::string(pos, end_int));
                    ret = lazy_entry(value);
                } catch (...) {
                    ec = error_code::invalid_integer;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return static_cast<int>(ec);
                }

                pos = end_int + 1;
                break;
            case 'e':
                if (depth_stack.empty()) {
                    ec = error_code::unexpected_end;
                    return static_cast<int>(ec);
                }

                depth = depth_stack.top();
                depth_stack.pop();
                break;
            case ':':
                // Handle string
                if (pos == start || !isdigit(pos[-1])) {
                    ec = error_code::invalid_string;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return static_cast<int>(ec);
                }

                const char* len_start = pos - 1;
                while (len_start > start && isdigit(*len_start))
                    len_start--;

                if (len_start == start && *len_start == '0' && pos - len_start > 1) {
                    ec = error_code::invalid_string;
                    if (error_pos)
                        *error_pos = static_cast<int>(len_start - start);
                    return static_cast<int>(ec);
                }

                int length = std::stoi(std::string(len_start, pos));
                if (pos + length > end) {
                    ec = error_code::unexpected_end;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return static_cast<int>(ec);
                }

                std::string str(pos + 1, pos + 1 + length);
                ret = lazy_entry(str);
                pos += length + 1;
                break;
            default:
                if (!isdigit(*pos)) {
                    ec = error_code::invalid_format;
                    if (error_pos)
                        *error_pos = static_cast<int>(pos - start);
                    return static_cast<int>(ec);
                }
        }

        pos++;
    }

    if (pos != end) {
        ec = error_code::unexpected_data;
        if (error_pos)
            *error_pos = static_cast<int>(pos - start);
        return static_cast<int>(ec);
    }

    if (!depth_stack.empty()) {
        ec = error_code::unexpected_end;
        return static_cast<int>(ec);
    }

    return 0;
}

int decode_lazy_structure(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<lazy_entry*> stack;
    const char* current = start;
    int depth = 0;
    int items = 0;

    while (current < end) {
        if (depth >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos) *error_pos = static_cast<int>(current - start);
            return static_cast<int>(ec);
        }

        if (items >= item_limit) {
            ec = error_code::item_limit_exceeded;
            if (error_pos) *error_pos = static_cast<int>(current - start);
            return static_cast<int>(ec);
        }

        switch (*current) {
            case 'd':
                depth++;
                stack.push(&ret);
                current++;
                continue;
            case 'l':
                depth++;
                lazy_entry list;
                stack.push(&list);
                current++;
                continue;
            case 'i':
                // Parse integer
                const char* int_end = std::find_if(current + 1, end, [](char c) { return c == 'e'; });
                if (int_end == end) {
                    ec = error_code::unexpected_end_of_input;
                    if (error_pos) *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }
                try {
                    int64_t value = std::stoll(std::string(current + 1, int_end - 1));
                    ret = lazy_entry{lazy_entry::integer_type(), value};
                } catch (...) {
                    ec = error_code::invalid_integer;
                    if (error_pos) *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }
                current = int_end + 1;
                items++;
                continue;
            case 'e':
                if (stack.empty()) {
                    ec = error_code::mismatched_e;
                    if (error_pos) *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }
                stack.pop();
                depth--;
                current++;
                continue;
            default:
                // Assume string
                const char* str_end = std::min(std::find_first_of(current, end, 'd', 'l', 'i', 'e'), end);
                lazy_entry str_entry{lazy_entry::string_type(), std::string(current, str_end - current)};
                if (!stack.empty()) {
                    stack.top()->add(str_entry);
                } else {
                    ret = str_entry;
                }
                items++;
                current = str_end;
                continue;
        }
    }

    if (current != end || !stack.empty()) {
        ec = error_code::incomplete_decoding;
        if (error_pos) *error_pos = static_cast<int>(current - start);
        return static_cast<int>(ec);
    }

    return 0;
}
